const setWarrantyClaimStatus = `-- name: SetWarrantyClaimStatus :one
UPDATE warranty_claims
SET status             = $1::varchar,
    rejection_reason   = CASE WHEN $1::varchar = 'rejected'
                              THEN $2::text ELSE rejection_reason END,
    decided_by_user_id = CASE WHEN $1::varchar IN ('approved', 'rejected')
                              THEN $3::bigint ELSE decided_by_user_id END,
    decided_at         = CASE WHEN $1::varchar IN ('approved', 'rejected')
                              THEN NOW() ELSE decided_at END,
    closed_at          = CASE WHEN $1::varchar = 'closed' THEN NOW() ELSE closed_at END,
    updated_by_user_id = $3::bigint
WHERE id = $4
  AND brand_id = $5
  AND status = $6::varchar
RETURNING id, uuid, organization_id, brand_id, claim_no, warranty_id, service_id, vehicle_id, customer_user_id, description, status, rejection_reason, coverage_check, ai_damage_type, ai_summary, ai_confidence, ai_triaged_at, reapply_service_id, decided_by_user_id, decided_at, created_by_user_id, updated_by_user_id, closed_at, created_at, updated_at
`

